// Manifest posture for removed CLI commands (task f3f15290). A manifest
// generated by the full template before the session-start producers were
// removed still wires `harness session-start ...` SessionStart hooks and the
// preflight-before-* policies, whose producer and `ux.run` lines name the
// removed `harness session-start preflight` / `harness preflight`. Such a
// manifest still parses, and `harness apply` re-renders those hooks as they
// stand, so `harness validate`, `harness doctor` and `harness apply` warn at
// every site (one warning per site, with its manifest path), and
// `harness validate --strict` fails on them.
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { stringify as yamlStringify } from "yaml";
import { apply } from "../../src/cli/apply/index.js";
import { doctor, format } from "../../src/cli/doctor/index.js";
import { run } from "../../src/cli/index.js";
import { formatReport, validate } from "../../src/cli/validate/index.js";
import type { ClaudeMcpExec } from "../../src/io/claude-mcp.js";
import { STUB_NPM_BIN_EXEC_UNKNOWN } from "../_helpers/npm-bin-exec.js";
import {
  legacyPreflightInvestigation,
  legacyPreflightPush,
} from "../_helpers/legacy-preflight-policies.js";

let cleanups: Array<() => void> = [];
afterEach(() => {
  for (const c of cleanups) c();
  cleanups = [];
});

function writeManifest(manifest: Record<string, unknown>): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "harness-removed-cmd-"));
  cleanups.push(() => fs.rmSync(dir, { recursive: true, force: true }));
  const file = path.join(dir, "harness.yaml");
  fs.writeFileSync(file, yamlStringify(manifest), "utf8");
  return file;
}

const intercept = (name: string, match: string, bashMatch?: string) => ({
  name,
  event: "PreToolUse",
  match,
  ...(bashMatch !== undefined ? { bash_match: bashMatch } : {}),
  command: "harness policy intercept",
  blocking: "hard",
  budget_ms: 15000,
});

// The removed producer hooks and the two preflight policies with their
// require-preflight-* hooks, in the order the pre-removal full template
// declared them, plus a live hook and a live policy that must stay silent.
function baseFullShaped(): Record<string, unknown> {
  const investigation = legacyPreflightInvestigation();
  const push = legacyPreflightPush();
  return {
    version: 1,
    tools: { mcp: [], cli: [], skills: { enabled: [], source_dirs: [] }, builtin: { known: [] } },
    memory: { directories: [] },
    hooks: [
      { name: "git-preflight", event: "SessionStart", command: "harness session-start preflight", blocking: false, budget_ms: 70000 },
      { name: "toolchain-parity", event: "SessionStart", command: "harness session-start toolchain-parity", blocking: false, budget_ms: 15000 },
      { name: "stale-base-check", event: "SessionStart", command: "harness session-start stale-base-check", blocking: false, budget_ms: 15000 },
      intercept("require-review-evidence", "mcp__github__merge_pull_request"),
      intercept("require-preflight-evidence", "Bash", investigation.trigger.bash_match),
      intercept("require-preflight-push-evidence", "Bash", push.trigger.bash_match),
    ],
    policies: [
      {
        name: "review-before-merge",
        description: "Live policy: its producer and ux.run lines name live commands.",
        trigger: { event: "PreToolUse", match: "mcp__github__merge_pull_request" },
        requires: { ledger_tag: "review:${SESSION_ID}", within: "1h" },
        hook: "require-review-evidence",
        enforcement: "block",
        producers: [
          { kind: "bash", command: "harness record review", description: "Records the review." },
          { kind: "mcp", verb: "mcp__grounding-mcp__ledger_add", example: "{}", description: "Direct write." },
        ],
        ux: { cannot: "You cannot merge yet.", required: ["a review"], run: ["harness record review"] },
      },
      investigation,
      push,
    ],
  };
}

// One warning per site, in manifest order.
const EXPECTED_SITES = [
  "hooks[0].command",
  "hooks[1].command",
  "hooks[2].command",
  "policies[1].producers[0].command",
  "policies[1].ux.run[0]",
  "policies[2].producers[0].command",
  "policies[2].ux.run[0]",
];

const isRemovedCommandDiag = (d: { message: string }) => d.message.includes(", removed in 1.0.0 (");

const NOOP_PROBES = {
  versionProbe: () => null,
  builtinRuntimeProbe: () => [] as string[],
  gitIgnoreProbe: () => null,
};

const NO_CLAUDE_CLI: ClaudeMcpExec = async () => ({ code: 127, stdout: "", stderr: "", enoent: true, timedOut: false });

describe("harness validate on a manifest that still calls removed commands", () => {
  it("warns once per site, naming the path, the removed command and the remedy", () => {
    const file = writeManifest(baseFullShaped());
    const result = validate({ configPath: file, ...NOOP_PROBES });
    expect(result.manifest).not.toBeNull();
    const diags = result.diagnostics.filter(isRemovedCommandDiag);
    expect(diags.map((d) => [d.path, d.severity])).toEqual(EXPECTED_SITES.map((p) => [p, "warning"]));

    const byPath = new Map(diags.map((d) => [d.path, d.message]));
    expect(byPath.get("hooks[0].command")).toBe(
      'calls "harness session-start", removed in 1.0.0 (the SessionStart producers are removed), so it fails with "unknown command"; ' +
        'delete hook "git-preflight" from the manifest (and every policy that names it), then re-run `harness apply`',
    );
    expect(byPath.get("policies[1].ux.run[0]")).toBe(
      'calls "harness preflight", removed in 1.0.0 (alias of the removed session-start preflight producer), so it fails with "unknown command"; ' +
        'delete policy "preflight-before-investigation" from the manifest (and its hook "require-preflight-evidence" when no other policy names it), then re-run `harness apply`',
    );
    expect(byPath.get("policies[2].producers[0].command")).toContain(
      'delete policy "preflight-before-push" from the manifest (and its hook "require-preflight-push-evidence"',
    );
    expect(formatReport(result)).toContain('WARN  hooks[1].command: calls "harness session-start", removed in 1.0.0');
  });

  it("--strict turns every site into an error", () => {
    const file = writeManifest(baseFullShaped());
    const result = validate({ configPath: file, strict: true, ...NOOP_PROBES });
    const diags = result.diagnostics.filter(isRemovedCommandDiag);
    expect(diags.map((d) => [d.path, d.severity])).toEqual(EXPECTED_SITES.map((p) => [p, "error"]));
    expect(result.errorCount).toBeGreaterThanOrEqual(EXPECTED_SITES.length);
  });

  it("a manifest without removed commands gives none, also under --strict", () => {
    const m = baseFullShaped();
    m["hooks"] = (m["hooks"] as Array<{ name: string }>).filter((h) => h.name === "require-review-evidence");
    m["policies"] = (m["policies"] as Array<{ name: string }>).filter((p) => p.name === "review-before-merge");
    const file = writeManifest(m);
    const result = validate({ configPath: file, strict: true, ...NOOP_PROBES });
    expect(result.manifest).not.toBeNull();
    expect(result.diagnostics.filter(isRemovedCommandDiag)).toEqual([]);
  });
});

describe("harness doctor on a manifest that still calls removed commands", () => {
  it("lists every site in the Manifest section and counts each as a warning", async () => {
    const file = writeManifest(baseFullShaped());
    const report = await doctor({
      configPath: file,
      homeOverride: path.dirname(file),
      shallow: true,
      versionProbe: () => null,
      pathEnv: "",
      npmBinExec: STUB_NPM_BIN_EXEC_UNKNOWN,
      claudeMcpExec: NO_CLAUDE_CLI,
    });
    const sites = report.manifest.warnings.filter((w) => w.includes(", removed in 1.0.0 ("));
    expect(sites.map((w) => w.slice(0, w.indexOf(": ")))).toEqual(EXPECTED_SITES);
    expect(report.warningCount).toBeGreaterThanOrEqual(EXPECTED_SITES.length);
    expect(format(report)).toContain('⚠ hooks[0].command: calls "harness session-start", removed in 1.0.0');
  });

  it("reports no such warning for a manifest without removed commands", async () => {
    const m = baseFullShaped();
    m["hooks"] = (m["hooks"] as Array<{ name: string }>).filter((h) => h.name === "require-review-evidence");
    m["policies"] = (m["policies"] as Array<{ name: string }>).filter((p) => p.name === "review-before-merge");
    const file = writeManifest(m);
    const report = await doctor({
      configPath: file,
      homeOverride: path.dirname(file),
      shallow: true,
      versionProbe: () => null,
      pathEnv: "",
      npmBinExec: STUB_NPM_BIN_EXEC_UNKNOWN,
      claudeMcpExec: NO_CLAUDE_CLI,
    });
    expect(report.manifest.warnings.filter((w) => w.includes(", removed in 1.0.0 ("))).toEqual([]);
  });
});

// apply needs no grounding wiring for SessionStart hooks alone, so the apply
// check uses the three removed producer hooks without the policies.
function hooksOnly(): Record<string, unknown> {
  const m = baseFullShaped();
  m["hooks"] = (m["hooks"] as unknown[]).slice(0, 3);
  m["policies"] = [];
  return m;
}

describe("harness apply on a manifest that still calls removed commands", () => {
  it("applies (it renders the manifest as it stands) and warns at every hook site", async () => {
    const file = writeManifest(hooksOnly());
    const result = await apply({ configPath: file, homeDir: path.dirname(file) });
    expect(result.outcome).toBe("applied");
    expect(result.warnings.filter((w) => w.includes(", removed in 1.0.0 ("))).toEqual([
      expect.stringMatching(/^hooks\[0\]\.command: calls "harness session-start"/),
      expect.stringMatching(/^hooks\[1\]\.command: calls "harness session-start"/),
      expect.stringMatching(/^hooks\[2\]\.command: calls "harness session-start"/),
    ]);
  });

  it("run() apply --dry-run prints the warning lines to stderr", async () => {
    const file = writeManifest(hooksOnly());
    let err = "";
    const code = await run({
      argv: ["apply", "--dry-run", "--config", file],
      stdout: () => {
        /* swallow */
      },
      stderr: (s) => {
        err += s;
      },
    });
    expect(code).toBe(0);
    expect(err).toContain('warning: hooks[0].command: calls "harness session-start", removed in 1.0.0');
  });
});
